var e=1,t=`ch03-wancheng`,n=`1.0.0`,r=`曹操不容易`,i=`第一章 · 建安二年 · 宛城一夜`,a=`兵不血刃拿下宛城，却因一夜荒唐折损典韦与长子曹昂——如果今夜你管住了自己，甚至反手设伏，大汉往后三十年会怎样改写？`,o=12,s={preset:`red-cliffs`,name:`宛城玄墨 · 夜火`,themeDir:`red-cliffs`,bgFile:`bg.jpg`,bgOpacity:.42,bgmFile:`bgm.mp3`,bgmOrigFile:`bgm-orig.mp3`,bgmLabel:`宛城 · 夜火 8x`,moodRates:{calm:1,tense:.94,cold:.9,fire:.88}},c={narrator:{id:`narrator`,name:`巡营所见`,side:`center`,tone:`neutral`},cao:{id:`cao`,name:`曹操`,role:`司空`,side:`right`,tone:`neutral`},dianwei:{id:`dianwei`,name:`典韦`,role:`校尉 · 帐前亲卫`,side:`left`,tone:`ok`},caoang:{id:`caoang`,name:`曹昂`,role:`长子 · 孝廉`,side:`left`,tone:`info`},zhangxiu:{id:`zhangxiu`,name:`张绣`,role:`北地枪王 · 降将`,side:`left`,tone:`warn`},jiaxu:{id:`jiaxu`,name:`贾诩`,role:`张绣谋士`,side:`left`,tone:`info`},caoanmin:{id:`caoanmin`,name:`曹安民`,role:`侄儿`,side:`left`,tone:`neutral`},scout:{id:`scout`,name:`夜巡校尉`,role:`中军暗哨`,side:`left`,tone:`warn`}},l={zou_refused:{type:`boolean`,initial:!1,description:`是否克己拒纳邹氏`},hucheer_exposed:{type:`boolean`,initial:!1,description:`是否识破私赐胡车儿黄金`},dirty_count:{type:`number`,initial:0,min:0,max:10}},u=[{id:`coin`,label:`威望`,initial:4,max:6,warnAt:1,collapseAt:0,collapseEndingId:`E_collapse_coin`,warnText:`宛城军纪涣散，荆北降将人人自危。`,redlineDesc:`威望清零时，南阳诸县群起反叛，曹军被困死在宛城外围。`},{id:`grain`,label:`军粮`,initial:4,max:6,warnAt:1,collapseAt:0,collapseEndingId:`E_collapse_grain`,warnText:`远征南阳补给拉长，行军仓已见底。`,redlineDesc:`军粮清零时，远征军无力回师许都，士卒溃散。`},{id:`troops`,label:`亲卫`,initial:4,max:6,warnAt:1,collapseAt:0,collapseEndingId:`E_collapse_troops`,warnText:`中军亲卫折损过半，帅帐门户洞开。`,redlineDesc:`亲卫清零时，西凉铁骑冲破中军大帐，司空无力突围。`}],d=`E_collapse_troops`,f=[{id:`zhangxiu_plot`,label:`张绣夜变`,initial:1,max:6,warnAt:4,overflowEndingId:`E_overflow_plot`,warnText:`贾诩已定下移营奇袭之策，西凉兵正暗中磨刀。`}],p=`N00_intro`,m=[{id:`act0`,num:`序`,title:`宛城受降`,startNode:`N00_intro`},{id:`act1`,num:`案壹`,title:`邹氏与贾诩`,startNode:`N01_zou`},{id:`act2`,num:`案贰`,title:`私赐胡车儿黄金`,startNode:`N02_hucheer`},{id:`act3`,num:`案叁`,title:`宛城火夜`,startNode:`N03_fire`}],h={wancheng:{id:`wancheng`,term:`宛城`,plain:`今河南南阳，南阳郡治，扼守中原南下荆州的咽喉要冲。`,source:`《三国志·武帝纪》`},hucheer:{id:`hucheer`,term:`胡车儿`,plain:`张绣帐下勇将，史载「勇冠其军」，曹操爱其骁勇而赐金，反令张绣疑心暗杀。`,source:`《三国志·张绣传》`},jiaxu:{id:`jiaxu`,term:`贾诩`,plain:`武威姑臧人，此时为张绣谋主，后劝张绣再降曹操，官至魏太尉。`,source:`《三国志·贾诩传》`}},g={sub_zou:{id:`sub_zou`,surface:`将军既降，一家老小皆当安顿`,decode:`你把人家婶母纳进后帐，张绣脸上挂不住，不反才怪。`,note:`张济遗孀邹氏乃张绣婶母，此事直接点燃宛城之变。`},sub_move:{id:`sub_move`,surface:`车重难行，请准士卒披甲过营`,decode:`贾诩在借移营之名，光明正大把全副武装的西凉兵开到你大帐门口。`,note:`史载张绣以此借口获准带甲穿营，随即发动奇袭。`}},_={},v=[{title:`宛城纳邹氏之祸`,when:{var:`zou_refused`,op:`==`,value:!0},canonNote:`史载建安二年曹操征张绣，绣降后操纳张济妻，绣恨之，遂用贾诩计夜袭。`,playerHit:`你克制住了这一夜的冲动，直接改写了典韦与曹昂的命运。`,playerMiss:`你还是重演了历史上的那一夜荒唐，让宛城陷入火海。`,source:`《三国志·张绣传》`}],y=JSON.parse(`{"N00_intro":{"id":"N00_intro","act":"序 · 宛城受降","title":"兵不血刃入南阳","kind":"scene","mood":"calm","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安二年春 · 宛城南门","text":"大军行至淯水，{{gloss:wancheng}}守将张绣竟不战而降。城头易帜，酒肉满营，连日奔波的北军终于松了一口气。长子曹昂牵着绝影马立在阶下，校尉典韦手持刃长一尺的大斧与多支长戟肃立帐门外。"},{"speaker":"caoang","sourceTag":"拟写","text":"父亲，张绣虽降，但西凉旧部皆百战悍卒，且其帐下谋士{{gloss:jiaxu}}素称毒士，不可不防。"},{"speaker":"cao","sourceTag":"拟写","text":"孤知道。进城先看清两笔账：一是城中降将人心，二是今夜酒宴后院的规矩。"}],"next":"N01_zou"},"N01_zou":{"id":"N01_zou","act":"案壹 · 邹氏与贾诩","title":"酒酣之后的暗流","kind":"scene","mood":"tense","lines":[{"speaker":"caoanmin","sourceTag":"拟写","text":"叔父，侄儿方才在城内馆驿见着张济遗孀邹氏，端的是国色天香。{{subtext:sub_zou}}，不如召入中军馆驿一叙？"},{"speaker":"dianwei","sourceTag":"拟写","text":"主公，张绣营里今夜灯火通明，好些西凉校尉喝醉了在街上摔酒碗，嘴里骂骂咧咧。"}],"interaction":{"type":"counter_case","title":"案壹 · 宛城馆驿密报","docTitle":"《南阳降营夜查簿》","prompt":"点开下方两条呈报核对巡营实情，再决定今夜如何落印：","minExpose":2,"claims":[{"id":"c1_zou","surface":"曹安民报称：张绣已归顺朝廷，纳其婶母乃「亲上加亲」，张绣不敢有怨。","proof":"巡营实查：张绣素重西凉宗族颜面，方才听闻传言已在府中摔碎茶盏，连夜闭门密会贾诩！"},{"id":"c1_jiaxu","surface":"降吏呈报：贾诩已收拾行囊准备告老还乡，绝不会生事。","proof":"巡营实查：贾诩门前车马未动，反倒有三名张绣亲信校尉连夜入府密议，必在图谋兵变！"}]},"choices":[{"id":"c1_canon_zou","label":"依史实纳邹氏入帐，顺手重金赐胡车儿拉拢张绣部下","hint":"威望 -1 · 张绣夜变 +2（史实顺势）","isBait":true,"stampKind":"approve","stampText":"纳之","replyText":"张绣既降便是我手下偏将，纳一遗孀何足挂齿？多赏他麾下勇将胡车儿些黄金便是！","effects":[{"kind":"resource","resource":"coin","delta":-1,"reason":"纳降将婶母且重赏其部将，引起张绣极度猜忌"},{"kind":"deadline","deadline":"zhangxiu_plot","delta":2,"reason":"张绣羞愤交加，当夜决定反叛"}],"next":"N02_hucheer"},{"id":"c1_whatif_refuse","label":"【架空】克己拒纳邹氏，斥退曹安民，连夜亲赴张绣府礼聘贾诩","hint":"平行世界线 · 典韦曹昂全活 · 改写三十年","stampKind":"reject","stampText":"克己","replyText":"糊涂东西！孤平天下岂能毁于一妇人？把曹安民轰出去！备厚礼，孤亲自去拜访张绣与贾文和！","effects":[{"kind":"var_set","var":"zou_refused","value":true},{"kind":"resource","resource":"coin","delta":1,"reason":"严明军纪、礼敬降将，南阳士民大悦"},{"kind":"deadline","deadline":"zhangxiu_plot","delta":-1,"reason":"彻底掐灭张绣反叛动机"}],"next":"N_WI_jiaxu_test"}]},"N_WI_jiaxu_join":{"id":"N_WI_jiaxu_join","act":"架空世界线 · 宛城夜访贾文和","title":"未燃的宛城之夜","kind":"scene","mood":"calm","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安二年春 · 张绣府中","text":"张绣见你单骑携长子曹昂亲至，又听闻你当场斥退曹安民、严令礼遇张济遗孀，顿时卸下防备大礼拜服。座侧的贾诩微微眯眼，端起酒盏起身一揖。"},{"speaker":"jiaxu","sourceTag":"推演","text":"司空克己复礼，胜过雄兵十万。今宛城已定、西凉悍骑尽归麾下，且令郎曹昂仁孝贤明、典韦猛将如云。不知司空下一步，是先借西凉骑兵南压刘表，还是趁势北回一口吃掉吕布？"},{"speaker":"caoang","sourceTag":"拟写","text":"父亲，孩儿愿随典韦将军为前锋，不论南下荆州还是北定徐州，绝不辱没曹氏门风！"}],"choices":[{"id":"wi_wan_south","label":"仿政治契约：许曹均娶张绣女联姻加封列侯，与曹昂共稳南阳淯水门户","hint":"军粮 -1 · 化解西凉客军猜忌，曹昂稳坐嫡长储位","stampKind":"approve","stampText":"定荆","replyText":"张绣部众仰食刘表，光靠受降留不住人心！孤以子曹均聘娶张绣之女、加封列侯食邑，子脩你协理南阳防务！","effects":[{"kind":"resource","resource":"grain","delta":-1,"reason":"大赏西凉客军并拨粮安置南阳防务"}],"next":"E_WI_caoang_heir"},{"id":"wi_wan_north","label":"带张绣、贾诩与完好无损的典韦立刻回师，提前合围下邳吕布","hint":"亲卫 +1 · 典韦战吕布，提前平定中原","stampKind":"reject","stampText":"北征","replyText":"荆州缓图，先带文和与西凉铁骑回师徐州！孤倒要看看典韦加张绣，吕布能撑几个回合！","effects":[{"kind":"resource","resource":"troops","delta":1,"reason":"张绣西凉铁骑完整编入中军"}],"next":"E_WI_dianwei_vs_lubu"}]},"E_WI_caoang_heir":{"id":"E_WI_caoang_heir","act":"架空结局 · 长子不死","title":"曹昂稳嫡长，曹魏无夺嫡","kind":"ending","mood":"calm","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安二十五年 · 许都魏王宫","text":"宛城没有那场大火。长子曹昂活了下来，以宽厚仁德深得士民与宗室拥戴，稳稳接过魏王大位——历史上那场耗尽曹氏元气的曹丕曹植夺嫡之争从未发生，更没有后世短命早逝与司马氏篡权之祸。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"结亲安张绣，长子曹昂稳坐嫡长储位","subtitle":"管住一夜冲动 · 改写曹魏百年国运","tone":"ok","verdict":"历史上曹昂战死导致丁夫人决裂离异、卞夫人扶正，才引爆日后曹丕曹植储位大争。你用联姻与克己保住长子，直接改写了曹魏法统。你克制住那一夜的放纵，换来典韦、曹昂、贾诩、张绣四赢满堂彩。","buildName":"清醒克己丞相","buildQuote":"少贪一夜温柔乡，多得百年曹魏稳江山。"}},"E_WI_dianwei_vs_lubu":{"id":"E_WI_dianwei_vs_lubu","act":"架空结局 · 古之恶来不死","title":"典韦双戟破吕布，提前扫平中原","kind":"ending","mood":"calm","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安三年春 · 下邳城外","text":"携贾诩奇谋、张绣西凉骑与完好无损的典韦回师徐州，你在下邳城外正面击溃吕布。古之恶来手提双铁戟与吕布大战百余合不落下风，随后官渡之战更提前两年到来，北方格局骤然加速。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"收贾诩合典韦，提前扫平中原","subtitle":"古之恶来健在 · 猛将谋主齐聚","tone":"ok","verdict":"没有宛城大败的伤筋动骨，曹操的军事机器提前三年进入全盛期，连袁绍都在河北感到了寒意。","buildName":"宛城满编收割派","buildQuote":"张绣成了先锋，贾诩成了军师，典韦还活蹦乱跳——吕布拿什么打？"}},"N02_hucheer":{"id":"N02_hucheer","act":"案贰 · 私赐胡车儿黄金","title":"移营借口与暗流涌动","kind":"scene","mood":"tense","lines":[{"speaker":"scout","sourceTag":"史载","text":"禀司空！张绣遣人来报，称其营盘逼仄、{{subtext:sub_move}}，请准许西凉部曲披甲穿过大营移驻城外高地。"},{"speaker":"dianwei","sourceTag":"拟写","text":"主公，主公昨日亲手赏了张绣贴身猛将{{gloss:hucheer}}一堆黄金——张绣听说后脸色煞白，疑心主公收买他左右行刺！"}],"interaction":{"type":"counter_case","title":"案贰 · 张绣移营请示","docTitle":"《西凉营移防呈文》","prompt":"核对张绣移营呈文里的两处致命破绽：","minExpose":2,"claims":[{"id":"c2_armor","surface":"呈文称：因辎重车多，请准士卒身披重甲、手持长矛穿过司空中军。","proof":"巡营实查：行军移营按律须卸甲收刃，哪有全副武装穿主帅中军的道理！分明是贾诩的奇袭毒计！"},{"id":"c2_spear","surface":"呈文称：张绣感念司空赏识部将胡车儿，特来谢恩。","proof":"巡营实查：《傅子》实情：私赐黄金给敌将贴身心腹犯了兵家大忌，张绣已断定司空欲行暗杀，决意先下手为强！"}]},"choices":[{"id":"c2_canon_allow","label":"依史实大度准其带甲移营，安抚降军疑心","hint":"张绣夜变 +2 · 步入宛城火夜（史实顺势）","isBait":true,"stampKind":"approve","stampText":"准移","replyText":"降军刚归顺难免多疑，准他们带甲过营，显我大度便是！","effects":[{"kind":"var_set","var":"hucheer_exposed","value":true},{"kind":"deadline","deadline":"zhangxiu_plot","delta":2,"reason":"放任西凉兵全副武装逼近中军帅帐"}],"next":"N03_fire"},{"id":"c2_whatif_ambush","label":"【架空】将计就计！假装准移营，大帐设空城火油阵反擒胡车儿与张绣","hint":"平行世界线 · 反杀贾诩奇袭计","stampKind":"dirty","stampText":"反伏","replyText":"好个贾文和，想在孤眼皮底下演带甲穿营？既然他疑心赐金欲刺，孤便假装松懈，暗中撤出中军主力、改在营外高地反包围！","effects":[{"kind":"var_set","var":"hucheer_exposed","value":true},{"kind":"resource","resource":"grain","delta":-1,"reason":"秘密调动中军精锐连夜布设反伏击阵"}],"next":"N_WI_interrogate_jiaxu"}]},"N_WI_counter_ambush":{"id":"N_WI_counter_ambush","act":"架空世界线 · 帅帐反伏击","title":"反客为主的宛城夜","kind":"scene","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安二年春 · 宛城三更","text":"张绣西凉骑兵刚穿入中军空营，便撞上典韦大斧亲卫与外围提前戒备的强弩阵！与此同时，带甲闯进中军的张绣一头扎进四面强弩火把的包围圈，连贾诩都脸色骤变。"},{"speaker":"zhangxiu","sourceTag":"拟写","text":"中计了！曹操竟早已识破移营之策！"},{"speaker":"cao","sourceTag":"拟写","text":"张绣已被困在网里，南面刘表的荆州援军正往宛城赶来。今夜是当场生擒张绣收编西凉骑，还是故意放走几人、拿宛城当鱼饵诱歼刘表援军？"}],"choices":[{"id":"wi_capture_zhangxiu","label":"生擒张绣、胡车儿与贾诩，收编整支西凉铁骑","hint":"亲卫 +1 · 宛城反杀大获全胜","stampKind":"approve","stampText":"生擒","replyText":"放箭吓住西凉兵，活捉张绣和贾诩！敢反孤的，孤今天就教他服服帖帖！","effects":[{"kind":"resource","resource":"troops","delta":1,"reason":"缴械收编西凉精锐骑兵"}],"next":"E_WI_wan_counter"},{"id":"wi_lure_liubiao","label":"连夜放出「曹操已死」假消息，诱歼南面赶来的刘表荆州援军","hint":"威望 +1 · 一石二鸟重创荆州","stampKind":"dirty","stampText":"诱荆","replyText":"把空帐点把火，放张绣几个败兵南逃报喜——等刘表援军笑呵呵赶来捡便宜，孤再一网打尽！","effects":[{"kind":"resource","resource":"coin","delta":1,"reason":"连环计重创荆州援军，威震南阳"}],"next":"E_WI_trap_liubiao"}]},"E_WI_wan_counter":{"id":"E_WI_wan_counter","act":"架空结局 · 宛城反杀","title":"毒士失算，宛城生擒张绣","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安二年春 · 宛城黎明","text":"贾诩生平最得意的一次奇袭，竟被你反手做成了瓮中捉鳖。胡车儿被典韦生擒，张绣束手就缚，你大笑着亲手解开贾诩绑绳——南阳全境一夜归心。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"宛城反杀，生擒张绣收西凉骑","subtitle":"识破毒士奇袭 · 识破移营穿插合围","tone":"ok","verdict":"贾诩算准了曹操的好色与大意，却没算到你会将计就计。宛城之耻一朝化作宛城大捷。","buildName":"反杀毒士大师","buildQuote":"贾文和，你这套带甲过营的戏，孤陪你演完了。"}},"E_WI_trap_liubiao":{"id":"E_WI_trap_liubiao","act":"架空结局 · 诱歼荆州援军","title":"一火两用，重创刘表主力","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安二年春 · 淯水南岸","text":"听到宛城大火、曹操身亡的假捷报，刘表兴冲冲派大军北上捡漏，结果在淯水南岸一头撞进你的伏兵阵。此战打得荆州十年不敢北窥中原。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"假败诱敌，一举重创刘表援军","subtitle":"连环反杀 · 荆北门户洞开","tone":"ok","verdict":"你不仅化解了宛城杀身之祸，还把火光变成了诱杀刘表援军的信号弹，堪称兵法诡道极致。","buildName":"诡道连环导演","buildQuote":"宛城的火是我自己点的，专等刘景升来送人头。"}},"N03_fire":{"id":"N03_fire","act":"案叁 · 宛城火夜","title":"营门血战与绝影受箭","kind":"scene","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安二年春 · 宛城中军火海","text":"鼓噪震天，火光四起！张绣西凉铁骑如潮水般涌向中军大帐。典韦手持长戟在营门迎敌，戟折后拔腰刀死战，一人挡住数十西凉悍卒，浑身创伤十余处仍怒目大骂。你的坐骑绝影中箭倒地，长子曹昂跃下战马将坐骑让给了你！"},{"speaker":"dianwei","sourceTag":"史载","text":"主公快走！贼兵不到十步——不到五步——只要俺典韦还有一口气，绝不叫他们踏进营门一步！"},{"speaker":"caoang","sourceTag":"拟写","text":"父亲快上马！孩儿替您挡住追兵！"}],"choices":[{"id":"c3_canon_escape","label":"含泪策马突围退往舞阴，保全主帅重整大军","hint":"亲卫 -2 · 典韦曹昂战死（史实结局）","isBait":true,"stampKind":"approve","stampText":"突围","replyText":"子脩！典韦！孤若活着回去，必为你们血洗宛城！","effects":[{"kind":"resource","resource":"troops","delta":-1,"reason":"火夜仓皇突围，亲卫精锐损失惨重"}],"next":"E_canon_wuyin"},{"id":"c3_whatif_rescue","label":"【架空】绝不独活！收拢严明执法弹压青州兵的于禁本部，杀回营门硬救典韦与曹昂","hint":"平行世界线 · 死战反冲救人","stampKind":"reject","stampText":"杀回","replyText":"孤连自己儿子和典韦都扔下，还当什么天下英雄！于禁何在，随孤杀回营门救人！","effects":[{"kind":"resource","resource":"troops","delta":-1,"reason":"逆流反冲火海强救营门亲卫"}],"next":"N_WI_yujin_rally"}]},"N_WI_bloody_rescue":{"id":"N_WI_bloody_rescue","act":"架空世界线 · 血战救营门","title":"绝境中的父子与恶来","kind":"scene","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安二年春 · 宛城营门火海","text":"你没有独自逃往舞阴，而是高举帅旗收拢了阵脚未乱的于禁部曲，反身杀回火海！西凉兵正忙着抢掠辎重，万没料到曹操竟敢带兵反冲，瞬间被杀得人仰马翻。"},{"speaker":"caoang","sourceTag":"拟写","text":"父亲！典韦将军已力竭倒在门柱旁，西凉骑兵正从两翼合围过来！"}],"choices":[{"id":"wi_save_dianwei","label":"死拼抢出典韦与曹昂，全军结圆阵边战边退回舞阴","hint":"军粮 -1 · 典韦重伤生还，古之恶来不死","stampKind":"approve","stampText":"抢人","replyText":"辎重粮草全不要了！把典韦抬上马背，护着子脩杀出一条血路！","effects":[{"kind":"resource","resource":"grain","delta":-1,"reason":"弃置全部辎重粮车换取抢人突围"}],"next":"E_WI_dianwei_lives"},{"id":"wi_counter_charge","label":"趁张绣乱抢辎重之际反烧其马厩，硬把宛城打成拉锯战","hint":"威望 +1 · 惨胜守住南阳","stampKind":"dirty","stampText":"反烧","replyText":"他们抢我的粮，我就烧他们的马！父子同战，今夜让张绣知道谁才是主宰！","effects":[{"kind":"resource","resource":"coin","delta":1,"reason":"绝境反冲打服诸将，曹军威望暴涨"}],"next":"E_WI_father_son_win"}]},"E_WI_dianwei_lives":{"id":"E_WI_dianwei_lives","act":"架空结局 · 恶来生还","title":"血战救典韦，古之恶来不死","kind":"ending","mood":"calm","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安二年夏 · 舞阴军帐","text":"你丢光了宛城的粮草辎重，却把浑身二十余处创口的典韦和满脸烟灰的曹昂活生生背出了火海。经此一夜，全军上下无不感泣效死，而活着走出宛城的典韦，日后在官渡与长坂坡成了令敌军闻风丧胆的噩梦。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"血战救典韦，古之恶来不死","subtitle":"弃辎重救袍泽 · 逆转最大遗憾","tone":"ok","verdict":"你用最不「理智」也最热血的选择，补上了三国历史上最让人意难平的一页。","buildName":"火海抢人铁汉","buildQuote":"粮草没了可以再挣，典韦和儿子没了拿天下也换不回。"}},"E_WI_father_son_win":{"id":"E_WI_father_son_win","act":"架空结局 · 父子同生","title":"宛城逆转，父子齐威震中原","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安二年春 · 宛城焦土","text":"西凉马厩起火引发炸营，张绣被迫仓皇撤出宛城。你与曹昂浑身浴血并肩立在残破营门前，经此一役，曹昂军功威望无人可及，再也无人敢轻视曹氏父子。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"父子同生，宛城绝境反胜","subtitle":"火海逆转 · 军心凝如铁石","tone":"ok","verdict":"谁说中了埋伏就只能逃？你抓住西凉兵抢掠失序的一瞬间反咬一口，把一场惨败硬生生打成了父子传世佳话。","buildName":"绝境反杀猛主","buildQuote":"张绣赢了上半夜，下半夜归我们父子。"}},"E_canon_wuyin":{"id":"E_canon_wuyin","act":"史实结局 · 痛哭典韦","title":"退保舞阴，泣祭古之恶来","kind":"ending","mood":"cold","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安二年春 · 舞阴军帐","text":"你活着退回了舞阴，却永远失去了长子曹昂、侄儿曹安民与死守营门的典韦。你在帐中抚案大哭：「吾折长子、爱侄，俱无深痛；独号泣典韦也！」——这一夜的代价远不止战损——丁夫人因痛失养子曹昂与你彻底决裂离异，卞夫人扶正，日后曹丕与曹植的储位暗战就此埋下伏笔。"}],"ending":{"badge":"史实收束 · CANON","title":"痛失典韦与曹昂，退守舞阴","subtitle":"重演历史 · 一夜荒唐换十年之痛","tone":"warn","verdict":"你完整走完了历史上那场著名的宛城惨剧。不妨跳回案壹或案贰，试试另外三条彻底改命的 What-If 世界线。","buildName":"史实重演者","buildQuote":"每当想起宛城那夜，便知顺风时最怕忘了防备。"}},"E_collapse_coin":{"id":"E_collapse_coin","act":"红线崩盘","title":"威望扫地，南阳群叛","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"text":"军纪败坏、威望归零，南阳各县纷纷倒戈响应张绣，大军陷入四面楚歌。"}],"ending":{"badge":"红线崩盘 · 威望归零","title":"南阳群叛，远征惨败","subtitle":"威望触及红线","tone":"danger","isCollapse":true,"verdict":"未战先失人心，宛城成了吞噬曹军的泥潭。","buildName":"失民心者","buildQuote":"打下城池容易，守住规矩难。"}},"E_collapse_grain":{"id":"E_collapse_grain","act":"红线崩盘","title":"南阳断炊，孤军溃散","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"text":"远征南阳粮道断绝，行军仓见底，全军未见敌影先自溃散。"}],"ending":{"badge":"红线崩盘 · 军粮归零","title":"孤军断炊，仓皇北逃","subtitle":"军粮触及红线","tone":"danger","isCollapse":true,"verdict":"客军远征最忌断粮，账本没算清便已满盘皆输。","buildName":"断粮远征军","buildQuote":"兵马未动，粮草先断。"}},"E_collapse_troops":{"id":"E_collapse_troops","act":"红线崩盘","title":"亲卫覆没，帅帐陷落","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"text":"中军亲卫耗尽，西凉铁骑冲破最后一道营栅，宛城夜火吞没了帅旗。"}],"ending":{"badge":"红线崩盘 · 亲卫归零","title":"宛城覆没，中军陷落","subtitle":"亲卫触及红线","tone":"danger","isCollapse":true,"verdict":"帅帐失去屏障，司空未能走出宛城这一夜。","buildName":"孤身陷阵者","buildQuote":"中军无卫，再高明的计策也来不及出手。"}},"E_overflow_plot":{"id":"E_overflow_plot","act":"死线溢出","title":"贾诩奇袭发难，措手不及","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"text":"张绣夜变死线拉满，贾诩抢在你反应之前发动总攻，大营一夜倾覆。"}],"ending":{"badge":"死线溢出 · 夜变爆发","title":"毒士先发，宛城倾覆","subtitle":"张绣夜变达到满格","tone":"danger","isDeadlineOverflow":true,"verdict":"一再纵容隐患发酵，终于等来了贾诩致命一击。","buildName":"慢半拍的帅帐","buildQuote":"在贾文和面前，慢一步就是生死之别。"}},"N_WI_jiaxu_test":{"id":"N_WI_jiaxu_test","act":"架空·承 · 荆州暗使搅局","title":"刘表的连夜离间","kind":"scene","mood":"tense","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安二年春 · 宛城西街","text":"你斥退曹安民、保住张济遗孀清誉的消息刚传开，襄阳刘表的密使竟连夜摸进宛城，企图用假军情挑唆张绣趁夜翻脸。你带着典韦与曹昂直接堵在了驿馆门外。"},{"speaker":"jiaxu","sourceTag":"拟写","text":"司空既然亲自来访，不妨先替张将军验一验荆州刚送来的这封「许都急报」——看看刘景升究竟在玩什么把戏。"}],"interaction":{"type":"counter_case","title":"架空柜台 · 荆州离间密信","docTitle":"《襄阳密使急札》","prompt":"当着张绣与贾诩的面戳穿刘表密使的两处假情报：","minExpose":2,"claims":[{"id":"wi1_c1","surface":"密信称：曹操此番收降只是缓兵之计，已命许都押送囚车准备诛杀张绣全族。","proof":"当堂翻出许都调令底簿：随军运来的全是封赏西凉将士的锦帛与冬粮，根本没有一辆囚车！"},{"id":"wi1_c2","surface":"密信称：刘表已遣五万荆州水陆大军北上，只要张绣夜袭成功便封其为南阳太守。","proof":"巡营实查：襄阳城门紧闭、刘表连两千援兵都没派出，只想拿张绣当替死鬼消耗曹军！"}]},"choices":[{"id":"wi1_expose_ok","label":"当众斩杀荆州密使，把调令与封赏文书亲手递给张绣","hint":"威望 +1 · 张绣彻底归心，进入大帐密议","stampKind":"approve","stampText":"立信","replyText":"张将军睁眼看看！刘表拿你当弃子，孤拿你当心腹！","effects":[{"kind":"resource","resource":"coin","delta":1,"reason":"当堂拆穿离间计，西凉降军彻底服气"}],"next":"N_WI_jiaxu_join"},{"id":"wi1_expose_dirty","label":"留密使活口，逼他带假消息回襄阳骗刘表开仓送粮","hint":"军粮 +1 · 顺手薅一把荆州羊毛","stampKind":"dirty","stampText":"反薅","replyText":"别急着杀！让他回襄阳报信说张绣已同意反水、先借五千斛急粮当军资！","effects":[{"kind":"resource","resource":"grain","delta":1,"reason":"反手从刘表手里骗来一批前线急粮"}],"next":"N_WI_jiaxu_join"}]},"N_WI_interrogate_jiaxu":{"id":"N_WI_interrogate_jiaxu","act":"架空·承 · 暗布空城杀局","title":"将计就计，应对移营合围","kind":"scene","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安二年春 · 宛城中军二更","text":"你假意批了移营文书，暗中却把亲卫全换成强弩手藏进马厩与屋檐。二更刚过，张绣借口春季营地潮湿车重难行，果然遣全副武装的西凉骑兵悄然穿插至中军侧翼，而城外西凉骑兵也开始悄悄裹马蹄。"},{"speaker":"dianwei","sourceTag":"拟写","text":"主公，俺已带亲卫在营门内侧备足长戟大斧与强弩，绝不让西凉马队近身——就等您一声令下！"}],"interaction":{"type":"counter_case","title":"架空柜台 · 反伏击布阵核验","docTitle":"《宛城三更杀局布防图》","prompt":"核对反伏击布防里的两处关键死穴，确保万无一失：","minExpose":2,"claims":[{"id":"wi2_c1","surface":"副将报称：只需守住帅帐正门，张绣中计后自然束手就擒。","proof":"巡营实查：贾诩素来留后手，必定在东墙角留了百名精骑接应，必须派曹昂提前封死东门！"},{"id":"wi2_c2","surface":"粮吏报称：中军粮草车不必转移，就近当掩体即可。","proof":"巡营实查：西凉兵最善夜战纵火，必须先把真粮车撤到北门，留空草车在营心诱敌放火！"}]},"choices":[{"id":"wi2_setup_clean","label":"命曹昂封东门、空车替真粮，静候三更梆子响","hint":"亲卫 +1 · 完美布阵进入收网时刻","stampKind":"approve","stampText":"布阵","replyText":"滴水不漏！今夜让贾文和见识一下，谁才是真正玩兵法的祖宗！","effects":[{"kind":"resource","resource":"troops","delta":1,"reason":"提前封死退路并保住粮草，伏兵士气大涨"}],"next":"N_WI_counter_ambush"},{"id":"wi2_setup_bait","label":"亲坐帅帐灯下读书当活饵，把张绣主力全吸进火油圈","hint":"威望 +1 · 孤身作饵震慑全军","stampKind":"dirty","stampText":"亲饵","replyText":"灯挑亮些！孤亲自坐在帐里翻《孙子兵法》，张绣见了我影子绝不会停步！","effects":[{"kind":"resource","resource":"coin","delta":1,"reason":"司空以身作饵，全军佩服胆魄"}],"next":"N_WI_counter_ambush"}]},"N_WI_yujin_rally":{"id":"N_WI_yujin_rally","act":"架空·承 · 乱军收拢于禁营","title":"绝境中的最后一张牌","kind":"scene","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安二年春 · 宛城北郊火光","text":"你没有独自策马北逃，而是冲出混乱劫掠的青州兵营盘，直奔军容严整的于禁本部大营。黑暗中溃兵互相踩踏，谣言四起，唯有于禁带着两千本营精兵列阵如山，冷眼斩了几个趁乱劫掠的青州兵。"},{"speaker":"scout","sourceTag":"拟写","text":"司空！乱军里有人高喊「于禁已投降张绣、正在杀自己人」，青州兵快要哗变了！"}],"interaction":{"type":"counter_case","title":"架空柜台 · 乱军谣言速断","docTitle":"《北郊溃兵口供》","prompt":"在半柱香内戳穿乱军中的两处致命误判，集结兵力杀回营门：","minExpose":2,"claims":[{"id":"wi3_c1","surface":"青州逃兵哭诉：于禁阵前斩杀自家弟兄，分明是准备倒戈张绣！","proof":"巡营实查：被于禁斩杀的全是趁夜抢掠百姓辎重的逃卒，于禁正一面掘壕一面等司空反攻！"},{"id":"wi3_c2","surface":"副将慌报：中军营门早已失守，典韦与曹昂必已战死，不必白白送命。","proof":"巡营实查：营门方向仍在响起典韦标志性的暴喝与喊杀声，西凉兵根本还没冲透中军！"}]},"choices":[{"id":"wi3_trust_yujin","label":"当众嘉奖于禁严明军纪，亲领其两千铁军反冲营门","hint":"威望 +1 · 整军杀回火海","stampKind":"approve","stampText":"反冲","replyText":"于文则有古名将风！于禁本部精兵听令，随孤回援营门，救典韦、救子脩！","effects":[{"kind":"resource","resource":"coin","delta":1,"reason":"临危辨忠奸，溃散各营瞬间重归帅旗"}],"next":"N_WI_bloody_rescue"},{"id":"wi3_burn_supply","label":"先收编戴罪立功的溃卒在西侧虚张火把声势，自己带精骑直插营门后背","hint":"亲卫 +1 · 声东击西破围","stampKind":"dirty","stampText":"虚火","replyText":"把所有火把绑在树枝上满山摇！张绣以为援军到了，咱们正好从背后捅穿他的包围圈！","effects":[{"kind":"resource","resource":"troops","delta":1,"reason":"疑兵分散西凉追兵，成功保住反攻战力"}],"next":"N_WI_bloody_rescue"}]}}`),b={schemaVersion:1,id:t,version:n,title:r,subtitle:i,tagline:a,estimatedMinutes:12,theme:s,cast:c,varsSchema:l,resources:u,multiCollapseEndingId:d,deadlines:f,startNode:p,acts:m,gloss:h,subtexts:g,refs:_,historyDossier:v,nodes:y};export{m as acts,c as cast,f as deadlines,b as default,o as estimatedMinutes,h as gloss,v as historyDossier,t as id,d as multiCollapseEndingId,y as nodes,_ as refs,u as resources,e as schemaVersion,p as startNode,g as subtexts,i as subtitle,a as tagline,s as theme,r as title,l as varsSchema,n as version};